package org.marketreview.nativeapp;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.function.BooleanSupplier;
import org.json.*;

/** New dedicated human drafts/observations. No migration of, or writes to, old production DB. */
final class SectorLeaderStore {
  private static final android.database.DatabaseErrorHandler KEEP_CORRUPT_FILE=corrupt->{throw new android.database.sqlite.SQLiteDatabaseCorruptException("人工龙头库损坏；原文件保留，拒绝自动删除或重建");};
  private static boolean sqliteHeader(File file){try(java.io.InputStream in=new java.io.FileInputStream(file)){byte[] header=new byte[16];int offset=0,n;while(offset<header.length&&(n=in.read(header,offset,header.length-offset))>0)offset+=n;return offset==16&&java.util.Arrays.equals(header,"SQLite format 3\000".getBytes(StandardCharsets.US_ASCII));}catch(java.io.IOException error){return false;}}
  private static void verifyExisting(SQLiteDatabase db)throws Exception{SectorLeaderModel.need(scalar(db,"PRAGMA application_id")==APP,"拒绝非本模块人工龙头数据库；未以写连接打开");SectorLeaderModel.need(scalar(db,"PRAGMA user_version")<=1,"人工龙头库版本过高，未改动");}

 final File file;static final int APP=0x534c5631;
 SectorLeaderStore(File file){this.file=file;}
 static long scalar(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){SectorLeaderModel.need(c.moveToFirst(),"人工库查询失败");return c.getLong(0);}}
 SQLiteDatabase open(boolean write,BooleanSupplier cancel)throws Exception{
    SectorLeaderModel.active(cancel);
    boolean fresh=false;
    if(!file.exists()){
      SectorLeaderModel.need(write,"人工龙头库不存在，未创建");
      File parent=file.getAbsoluteFile().getParentFile();SectorLeaderModel.need(parent.isDirectory()||parent.mkdirs(),"人工龙头库目录不可创建");
      SectorLeaderModel.need(file.createNewFile(),"人工龙头库路径出现并发文件；未采用外来库");fresh=true;
    }
    if(!fresh){
      SectorLeaderModel.need(sqliteHeader(file),"人工龙头库文件头无效；保留原文件");
      try(SQLiteDatabase guard=SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS,KEEP_CORRUPT_FILE)){verifyExisting(guard);}
    }
    SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.NO_LOCALIZED_COLLATORS|(write?SQLiteDatabase.OPEN_READWRITE:SQLiteDatabase.OPEN_READONLY),KEEP_CORRUPT_FILE);
  try{try(Cursor c=db.rawQuery("PRAGMA busy_timeout=100",null)){c.moveToFirst();}long app=scalar(db,"PRAGMA application_id");SectorLeaderModel.need(fresh?app==0&&scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")==0:app==APP,"不是人工龙头专用库，未改动");SectorLeaderModel.need(scalar(db,"PRAGMA user_version")<=1,"人工库版本过高");if(write){db.execSQL("PRAGMA synchronous=FULL");db.beginTransaction();try{db.execSQL("CREATE TABLE IF NOT EXISTS config(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,digest TEXT NOT NULL,payload BLOB NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,sector_id TEXT NOT NULL,captured_at TEXT NOT NULL,digest TEXT NOT NULL,payload BLOB NOT NULL)");db.execSQL("CREATE INDEX IF NOT EXISTS observation_sector_time ON observations(sector_id,captured_at DESC,id)");db.execSQL("CREATE TABLE IF NOT EXISTS imports(digest TEXT PRIMARY KEY,applied_at TEXT NOT NULL)");db.execSQL("PRAGMA application_id="+APP);db.execSQL("PRAGMA user_version=1");SectorLeaderModel.active(cancel);db.setTransactionSuccessful();}finally{db.endTransaction();}}return db;}catch(Exception e){db.close();throw e;}
 }
 static JSONObject payload(Cursor c,int col,int sizeCol,int digestCol,int limit)throws Exception{SectorLeaderModel.need(c.getLong(sizeCol)>0&&c.getLong(sizeCol)<=limit,"人工数据长度无效");byte[] bytes=c.getBlob(col);SectorLeaderModel.need(SectorLeaderModel.hash(bytes).equals(c.getString(digestCol)),"人工数据摘要不符");return new JSONObject(new String(bytes,StandardCharsets.UTF_8));}
 JSONObject config(SQLiteDatabase db)throws Exception{try(Cursor c=db.rawQuery("SELECT CASE WHEN length(payload)<=2097152 THEN payload ELSE NULL END,length(payload),digest,revision FROM config WHERE id=1",null)){if(!c.moveToFirst())return SectorLeaderModel.empty();JSONObject result=payload(c,0,1,2,SectorLeaderModel.MAX);SectorLeaderModel.validate(result);SectorLeaderModel.need(result.getLong("revision")==c.getLong(3),"人工配置版本不符");return result;}}
 synchronized JSONObject read(BooleanSupplier cancel)throws Exception{SectorLeaderModel.active(cancel);if(!file.exists())return SectorLeaderModel.empty();try(SQLiteDatabase db=open(false,cancel)){JSONObject c=config(db);SectorLeaderModel.active(cancel);return c;}}
 JSONObject write(SQLiteDatabase db,JSONObject input,long expected,BooleanSupplier cancel)throws Exception{
  SectorLeaderModel.validate(input);SectorLeaderModel.need(expected>=0&&expected<9007199254740991L,"人工配置版本超范围");SectorLeaderModel.need(config(db).getLong("revision")==expected,"人工稿已被修改，请重新读取后保存");JSONObject next=new JSONObject(input.toString()).put("revision",expected+1).put("updatedAt",Instant.now().toString());SectorLeaderModel.validate(next);byte[] bytes=next.toString().getBytes(StandardCharsets.UTF_8);ContentValues values=new ContentValues();values.put("id",1);values.put("revision",expected+1);values.put("digest",SectorLeaderModel.hash(bytes));values.put("payload",bytes);SectorLeaderModel.need(db.insertWithOnConflict("config",null,values,SQLiteDatabase.CONFLICT_REPLACE)!=-1,"人工稿写入失败");SectorLeaderModel.need(SectorLeaderModel.equal(config(db),next),"人工稿写后读回不符");SectorLeaderModel.active(cancel);return next;
 }
 synchronized JSONObject save(JSONObject input,long expected,BooleanSupplier cancel)throws Exception{try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{JSONObject result=write(db,input,expected,cancel);SectorLeaderModel.active(cancel);db.setTransactionSuccessful();return result;}finally{db.endTransaction();}}}
 synchronized JSONObject importPreview(JSONObject preview,BooleanSupplier cancel)throws Exception{try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{String digest=preview.getString("digest");SectorLeaderModel.need(digest.matches("[0-9a-f]{64}"),"导入摘要错误");try(Cursor c=db.rawQuery("SELECT 1 FROM imports WHERE digest=?",new String[]{digest})){if(c.moveToFirst()){SectorLeaderModel.active(cancel);db.setTransactionSuccessful();return config(db);}}JSONObject result=write(db,preview.getJSONObject("config"),preview.getLong("expectedRevision"),cancel);ContentValues v=new ContentValues();v.put("digest",digest);v.put("applied_at",Instant.now().toString());SectorLeaderModel.need(db.insertOrThrow("imports",null,v)!=-1,"导入回执未保存");SectorLeaderModel.active(cancel);db.setTransactionSuccessful();return result;}finally{db.endTransaction();}}}
 synchronized void saveShot(JSONObject s,BooleanSupplier cancel)throws Exception{SectorLeaderModel.validateShot(s);try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{SectorLeaderModel.need(config(db).getLong("revision")==s.getLong("configRevision"),"人工名单版本已变化，请重新冻结观察");SectorLeaderModel.need(scalar(db,"SELECT count(*) FROM observations")<2000,"历史已达2000条，请明确清理后保存");byte[] bytes=s.toString().getBytes(StandardCharsets.UTF_8);ContentValues v=new ContentValues();v.put("id",s.getString("id"));v.put("sector_id",s.getString("sectorId"));v.put("captured_at",s.getString("capturedAt"));v.put("digest",SectorLeaderModel.hash(bytes));v.put("payload",bytes);SectorLeaderModel.need(db.insertOrThrow("observations",null,v)!=-1,"冻结观察保存失败");SectorLeaderModel.active(cancel);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 synchronized JSONArray history(String sectorId,int offset,int limit,BooleanSupplier cancel)throws Exception{SectorLeaderModel.need(offset>=0&&offset<=2000&&limit>0&&limit<=100,"历史分页超范围");JSONArray out=new JSONArray();if(!file.exists())return out;try(SQLiteDatabase db=open(false,cancel);Cursor c=db.rawQuery("SELECT CASE WHEN length(payload)<=8388608 THEN payload ELSE NULL END,length(payload),digest FROM observations WHERE sector_id=? ORDER BY captured_at DESC,id DESC LIMIT ? OFFSET ?",new String[]{sectorId,String.valueOf(limit),String.valueOf(offset)})){while(c.moveToNext()){SectorLeaderModel.active(cancel);JSONObject s=payload(c,0,1,2,4*SectorLeaderModel.MAX);SectorLeaderModel.validateShot(s);SectorLeaderModel.need(s.getString("sectorId").equals(sectorId),"历史板块身份不符");out.put(s);}}return out;}
 synchronized JSONObject restoreSnapshot(BooleanSupplier cancel)throws Exception{return SectorObservationDatabase.readFile(this,cancel,null,null);}
 synchronized JSONObject previewRestore(JSONObject input,JSONObject before,BooleanSupplier cancel)throws Exception{return SectorObservationDatabase.preview(this,input,before,cancel);}
 synchronized JSONObject commitRestore(JSONObject preview,BooleanSupplier cancel)throws Exception{return SectorObservationDatabase.commit(this,preview,cancel,null);}
 synchronized JSONObject commitRestore(JSONObject preview,BooleanSupplier cancel,SectorObservationDatabase.Hook beforeCommit)throws Exception{return SectorObservationDatabase.commit(this,preview,cancel,beforeCommit);}
 synchronized boolean verifyRestore(JSONObject preview,JSONObject receipt,JSONObject after,BooleanSupplier cancel)throws Exception{return SectorObservationDatabase.verify(this,preview,receipt,after,cancel);}
 synchronized int count(String sectorId)throws Exception{if(!file.exists())return 0;try(SQLiteDatabase db=open(false,null);Cursor c=db.rawQuery("SELECT count(*) FROM observations WHERE sector_id=?",new String[]{sectorId})){c.moveToFirst();return c.getInt(0);}}
 synchronized JSONArray historyBoards(BooleanSupplier cancel)throws Exception{JSONArray out=new JSONArray();if(!file.exists())return out;try(SQLiteDatabase db=open(false,cancel);Cursor c=db.rawQuery("SELECT sector_id,count(*) FROM observations GROUP BY sector_id ORDER BY max(captured_at) DESC",null)){while(c.moveToNext()){SectorLeaderModel.active(cancel);out.put(new JSONObject().put("id",c.getString(0)).put("count",c.getInt(1)));}}return out;}
 synchronized JSONObject trend(String sectorId,String leaderId,String fullId,BooleanSupplier cancel)throws Exception{JSONArray samples=new JSONArray();if(!file.exists())return SectorLeaderModel.trend(samples,leaderId,fullId);int count=0;JSONObject latest=null,previous=null;try(SQLiteDatabase db=open(false,cancel);Cursor c=db.rawQuery("SELECT CASE WHEN length(payload)<=8388608 THEN payload ELSE NULL END,length(payload),digest FROM observations WHERE sector_id=? ORDER BY captured_at DESC,id DESC",new String[]{sectorId})){while(c.moveToNext()){SectorLeaderModel.active(cancel);JSONObject s=payload(c,0,1,2,4*SectorLeaderModel.MAX);SectorLeaderModel.validateShot(s);SectorLeaderModel.need(s.getString("sectorId").equals(sectorId),"历史板块身份不符");JSONArray rows=s.getJSONArray("rows");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!r.getString("id").equals(leaderId)||!r.optString("fullId").equals(fullId))continue;count++;if(latest==null)latest=new JSONObject().put("capturedAt",s.getString("capturedAt")).put("rows",new JSONArray().put(r));else if(previous==null&&SectorLeaderModel.value(r.opt("change"))!=null)previous=new JSONObject().put("capturedAt",s.getString("capturedAt")).put("rows",new JSONArray().put(r));}}}if(latest!=null)samples.put(latest);if(previous!=null)samples.put(previous);return SectorLeaderModel.trend(samples,leaderId,fullId).put("samples",count);}
 synchronized int prune(String sectorId,int keep,int expectedCount,BooleanSupplier cancel)throws Exception{SectorLeaderModel.need(keep>=1&&keep<=2000,"保留数必须为1至2000");try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{try(Cursor c=db.rawQuery("SELECT count(*) FROM observations WHERE sector_id=?",new String[]{sectorId})){c.moveToFirst();SectorLeaderModel.need(c.getInt(0)==expectedCount,"历史已变化，请重新预览清理");}db.execSQL("DELETE FROM observations WHERE id IN (SELECT id FROM observations WHERE sector_id=? ORDER BY captured_at DESC,id DESC LIMIT -1 OFFSET ?)",new Object[]{sectorId,keep});SectorLeaderModel.active(cancel);db.setTransactionSuccessful();return Math.max(0,expectedCount-keep);}finally{db.endTransaction();}}}
}
